import { IEntityBase } from '@droid/project-v2-interface';
import { googleGeminiIntersectionLocale } from '@0xff336699/js-i18n-lngs';
import { Box, TextField, MenuItem, Grid2, Typography, Divider } from '@mui/material';
import { useProxyWatch, useProxyWatchUpdates, useTranslation } from '@fanfanlo';
import React from 'react';
import { EntityChipsEditor } from './EntityChipsEditor';

// 为了支持 Project 特有字段，定义一个扩展接口
interface IEntityWithProjectFields extends IEntityBase {
    title?: string;
    subtitle?: string;
    tags?: string[];
    categories?: string[];
    briefDescription?: any;
    fullIntroduction?: any;
}

export interface EntityBasicInfoEditorProps<T extends IEntityBase> {
    entity: T;
    onChange?: (field: keyof IEntityWithProjectFields, value: any) => void;
    showTitle?: boolean;      // 是否显示 title (Project)
    showSubtitle?: boolean;   // 是否显示 subtitle (Project)
    showTags?: boolean;       // 是否显示标签
    showCategories?: boolean; // 是否显示分类
    disabled?: boolean;
    componentName?: string;   // 用于生成 testid
}

export function EntityBasicInfoEditor<T extends IEntityBase>({
    entity,
    onChange,
    showTitle = false,
    showSubtitle = false,
    showTags = false,
    showCategories = false,
    disabled = false,
    componentName = 'EntityBasicInfoEditor'
}: EntityBasicInfoEditorProps<T>) {
    const { t, i18n } = useTranslation('droid-project-v2-ui/ui/components/entity-settings/content');
    const entityWithProject = entity as unknown as IEntityWithProjectFields;

    // 使用 useProxyWatch 监听基础字段，确保输入响应
    const [name] = useProxyWatch(entityWithProject, 'name' as any, entityWithProject.name || '');
    const [sourceLang] = useProxyWatch(entityWithProject, 'sourceLang' as any, entityWithProject.sourceLang || '');
    const [title] = useProxyWatch(entityWithProject, 'title' as any, entityWithProject.title || '');
    const [subtitle] = useProxyWatch(entityWithProject, 'subtitle' as any, entityWithProject.subtitle || '');
    
    // 使用 useProxyWatchUpdates 监听复杂对象，实现局部更新
    const [briefDescription] = useProxyWatchUpdates(entityWithProject, 'briefDescription' as any, entityWithProject.briefDescription || { type: 'text', content: '' });
    const [fullIntroduction] = useProxyWatchUpdates(entityWithProject, 'fullIntroduction' as any, entityWithProject.fullIntroduction || { type: 'text', content: '' });
    const [tags] = useProxyWatchUpdates(entityWithProject, 'tags' as any, entityWithProject.tags || []);
    const [categories] = useProxyWatchUpdates(entityWithProject, 'categories' as any, entityWithProject.categories || []);

    // 默认语言逻辑
    const defaultLang = i18n.language || 'zh-CN';

    // 基础字段直接赋值逻辑 (Proxy Mutation)
    const handleNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        entity.name = e.target.value;
        onChange?.('name', e.target.value);
    };

    const handleSourceLangChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        entity.sourceLang = e.target.value as any;
        onChange?.('sourceLang', e.target.value);
    };

    const handleTitleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        entityWithProject.title = e.target.value;
        onChange?.('title', e.target.value);
    };

    const handleSubtitleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        entityWithProject.subtitle = e.target.value;
        onChange?.('subtitle', e.target.value);
    };

    // 标签和分类的直接代理操作逻辑
    const handleAddTag = (tag: string) => {
        if (!entityWithProject.tags) entityWithProject.tags = [];
        entityWithProject.tags.push(tag);
    };

    const handleDeleteTag = (tag: string) => {
        const idx = entityWithProject.tags?.indexOf(tag);
        if (idx !== undefined && idx !== -1) {
            entityWithProject.tags?.splice(idx, 1);
        }
    };

    const handleAddCategory = (cat: string) => {
        if (!entityWithProject.categories) entityWithProject.categories = [];
        entityWithProject.categories.push(cat);
    };

    const handleDeleteCategory = (cat: string) => {
        const idx = entityWithProject.categories?.indexOf(cat);
        if (idx !== undefined && idx !== -1) {
            entityWithProject.categories?.splice(idx, 1);
        }
    };

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
            
            {/* 1. 核心标识信息 */}
            <Box>
                <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 1 }}>
                    {t('EntityBasicInfoEditor.label.identity')}
                </Typography>
                <Grid2 container spacing={2}>
                    {/* Name: 内部标识 */}
                    <Grid2 size={{ xs: 12, md: 6 }}>
                        <TextField
                            fullWidth
                            label={t('EntityBasicInfoEditor.field.name')}
                            helperText={t('EntityBasicInfoEditor.helper.name')}
                            value={name}
                            onChange={handleNameChange}
                            disabled={disabled}
                            variant="outlined"
                            size="small"
                            data-testid={`${componentName}__nameInput__01JK2VSZ1A2B3C4D`}
                            data-test-comment="内部名称输入框，用于设置实体的唯标示"
                        />
                    </Grid2>

                    {/* SourceLang: 源语言 */}
                    <Grid2 size={{ xs: 12, md: 6 }}>
                        <TextField
                            select
                            fullWidth
                            label={t('EntityBasicInfoEditor.field.sourceLang')}
                            helperText={t('EntityBasicInfoEditor.helper.sourceLang')}
                            placeholder={defaultLang}
                            value={sourceLang}
                            onChange={handleSourceLangChange}
                            disabled={disabled}
                            variant="outlined"
                            size="small"
                            data-testid={`${componentName}__sourceLangSelect__01JK2VSZ2A3B4C5D`}
                            data-test-comment="源语言选择框，选择原始内容的语言类型"
                        >
                            <MenuItem value="">
                                <em>{t('EntityBasicInfoEditor.option.none')}</em>
                            </MenuItem>
                            {Object.entries(googleGeminiIntersectionLocale).map(([key, label]) => (
                                <MenuItem key={key} value={key}>
                                    {label} ({key})
                                </MenuItem>
                            ))}
                        </TextField>
                    </Grid2>
                </Grid2>
            </Box>

            {/* 2. 项目专用显示信息 (仅当启用时显示) */}
            {(showTitle || showSubtitle || showTags || showCategories) && (
                <Box>
                    <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 1 }}>
                        {t('EntityBasicInfoEditor.label.display')}
                    </Typography>
                    <Grid2 container spacing={2}>
                        {showTitle && (
                            <Grid2 size={{ xs: 12 }}>
                                <TextField
                                    fullWidth
                                    label={t('EntityBasicInfoEditor.field.title')}
                                    helperText={t('EntityBasicInfoEditor.helper.title')}
                                    value={title}
                                    onChange={handleTitleChange}
                                    disabled={disabled}
                                    data-testid={`${componentName}__titleInput__01JK2VSZ3A4B5C6D`}
                                    data-test-comment="显示标题输入框，面向用户的正式名称"
                                />
                            </Grid2>
                        )}
                        {showSubtitle && (
                            <Grid2 size={{ xs: 12 }}>
                                <TextField
                                    fullWidth
                                    label={t('EntityBasicInfoEditor.field.subtitle')}
                                    value={subtitle}
                                    onChange={handleSubtitleChange}
                                    disabled={disabled}
                                    data-testid={`${componentName}__subtitleInput__01JK2VSZ4A5B6C7D`}
                                    data-test-comment="副标题输入框，提供额外辅助说明"
                                />
                            </Grid2>
                        )}
                        {showTags && (
                            <Grid2 size={{ xs: 12, md: 6 }}>
                                <EntityChipsEditor
                                    label={t('EntityBasicInfoEditor.field.tags')}
                                    items={tags}
                                    onAdd={handleAddTag}
                                    onDelete={handleDeleteTag}
                                    disabled={disabled}
                                    placeholder={t('EntityBasicInfoEditor.helper.tags')}
                                    componentName={`${componentName}Tags`}
                                />
                            </Grid2>
                        )}
                        {showCategories && (
                            <Grid2 size={{ xs: 12, md: 6 }}>
                                <EntityChipsEditor
                                    label={t('EntityBasicInfoEditor.field.categories')}
                                    items={categories}
                                    onAdd={handleAddCategory}
                                    onDelete={handleDeleteCategory}
                                    disabled={disabled}
                                    placeholder={t('EntityBasicInfoEditor.helper.categories')}
                                    componentName={`${componentName}Categories`}
                                />
                            </Grid2>
                        )}
                    </Grid2>
                </Box>
            )}

            <Divider />

            {/* 3. 详细描述信息 */}
            <Box>
                <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 1 }}>
                    {t('EntityBasicInfoEditor.label.description')}
                </Typography>
                <Grid2 container spacing={2}>
                    {/* 一行简介 */}
                    <Grid2 size={{ xs: 12 }}>
                        <TextField
                            fullWidth
                            label={t('EntityBasicInfoEditor.field.briefDescription')}
                            helperText={t('EntityBasicInfoEditor.helper.briefDescription')}
                            value={briefDescription.content || ''}
                            onChange={(e) => {
                                entityWithProject.briefDescription = {
                                    type: 'text',
                                    content: e.target.value
                                };
                                onChange?.('briefDescription', entityWithProject.briefDescription);
                            }}
                            disabled={disabled}
                            multiline
                            rows={2}
                            data-testid={`${componentName}__briefDescInput__01JK2VSZ5A6B7C8D`}
                            data-test-comment="一句话简介输入框，简要描述实体功能"
                        />
                    </Grid2>

                    {/* 完整介绍 */}
                     <Grid2 size={{ xs: 12 }}>
                        <TextField
                            fullWidth
                            label={t('EntityBasicInfoEditor.field.introduction')}
                            helperText={t('EntityBasicInfoEditor.helper.introduction')}
                            value={fullIntroduction.content || ''}
                            onChange={(e) => {
                                entityWithProject.fullIntroduction = {
                                    type: 'text',
                                    content: e.target.value
                                };
                                onChange?.('fullIntroduction', entityWithProject.fullIntroduction);
                            }}
                            disabled={disabled}
                            multiline
                            minRows={4}
                            data-testid={`${componentName}__introInput__01JK2VSZ6A7B8C9D`}
                            data-test-comment="完整介绍输入框，详细说明实体的功能和用法"
                        />
                    </Grid2>
                </Grid2>
            </Box>
        </Box>
    );
}
