import React, { useState } from 'react';
import { 
    Box, 
    Typography, 
    Chip, 
    IconButton, 
    Dialog, 
    DialogTitle, 
    DialogContent, 
    DialogActions, 
    TextField, 
    Button,
    Paper
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import { useTranslation } from '@fanfanlo';

export interface EntityChipsEditorProps {
    label: string;
    items: string[];
    onChange?: (items: string[]) => void;
    onAdd?: (item: string) => void;
    onDelete?: (item: string) => void;
    placeholder?: string;
    disabled?: boolean;
    componentName?: string; // 用于生成 testid
}

export function EntityChipsEditor({ 
    label, 
    items = [], 
    onChange, 
    onAdd,
    onDelete,
    placeholder,
    disabled = false,
    componentName = 'EntityChipsEditor'
}: EntityChipsEditorProps) {
    const { t } = useTranslation('droid-project-v2-ui/ui/components/entity-settings/content');
    const [open, setOpen] = useState(false);
    const [inputValue, setInputValue] = useState('');

    const handleOpen = () => {
        if (disabled) return;
        setOpen(true);
        setInputValue('');
    };

    const handleClose = () => {
        setOpen(false);
    };

    const handleAdd = () => {
        const trimmed = inputValue.trim();
        if (trimmed && !items.includes(trimmed)) {
            if (onAdd) {
                onAdd(trimmed);
            } else if (onChange) {
                onChange([...items, trimmed]);
            }
        }
        handleClose();
    };

    const handleDelete = (itemToDelete: string) => {
        if (onDelete) {
            onDelete(itemToDelete);
        } else if (onChange) {
            onChange(items.filter(item => item !== itemToDelete));
        }
    };

    const handleKeyPress = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter') {
            handleAdd();
        }
    };

    return (
        <Box sx={{ mb: 2 }}>
            <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mb: 0.5 }}>
                {label}
            </Typography>
            
            <Paper 
                variant="outlined" 
                sx={{ 
                    p: 1, 
                    minHeight: 48, 
                    display: 'flex', 
                    flexWrap: 'wrap', 
                    gap: 1, 
                    alignItems: 'center',
                    bgcolor: 'background.default',
                    borderColor: 'divider',
                    '&:hover': {
                        borderColor: disabled ? 'divider' : 'primary.main'
                    }
                }}
            >
                {items.map((item, index) => (
                    <Chip
                        key={item}
                        label={item}
                        size="small"
                        onDelete={disabled ? undefined : () => handleDelete(item)}
                        color="primary"
                        variant="outlined"
                        data-testid={`${componentName}__chipItem__01JK2V3RZA5B1H8S__${index}`}
                        data-test-comment={`展示项：${item}，点击 X 按钮可将其移除`}
                    />
                ))}
                
                {!disabled && (
                    <IconButton 
                        size="small" 
                        onClick={handleOpen}
                        sx={{ 
                            border: '1px dashed', 
                            borderColor: 'divider', 
                            borderRadius: '16px',
                            px: 1
                        }}
                        data-testid={`${componentName}__addButton__01JK2V3SZA6C2H9T`}
                        data-test-comment="添加按钮，点击后弹出输入对话框"
                    >
                        <AddIcon fontSize="small" />
                    </IconButton>
                )}

                {items.length === 0 && !disabled && (
                    <Typography 
                        variant="body2" 
                        color="text.disabled" 
                        onClick={handleOpen}
                        sx={{ cursor: 'pointer', ml: 1 }}
                        data-testid={`${componentName}__emptyPlaceholder__01JK2V3TZA7D3H0U`}
                        data-test-comment="空占位提示，点击同样可弹出添加对话框"
                    >
                        {placeholder || t('EntityChipsEditor.placeholder.add')}
                    </Typography>
                )}
            </Paper>

            <Dialog 
                open={open} 
                onClose={handleClose} 
                fullWidth 
                maxWidth="xs"
                data-testid={`${componentName}__dialog__01JK2V3UZA8E4H1V`}
                data-test-comment="添加内容的输入对话框"
            >
                <DialogTitle>{t('EntityChipsEditor.dialog.title')}</DialogTitle>
                <DialogContent>
                    <TextField
                        autoFocus
                        margin="dense"
                        label={label}
                        fullWidth
                        variant="outlined"
                        value={inputValue}
                        onChange={(e) => setInputValue(e.target.value)}
                        onKeyPress={handleKeyPress}
                        data-testid={`${componentName}__dialogInput__01JK2V3VZA9F5H2W`}
                        data-test-comment={`输入框：用于输入新的${label}`}
                    />
                </DialogContent>
                <DialogActions>
                    <Button 
                        onClick={handleClose}
                        data-testid={`${componentName}__dialogCancel__01JK2V3WZA0G6H3X`}
                        data-test-comment="取消按钮，关闭弹窗不保存"
                    >
                        {t('EntityChipsEditor.action.cancel')}
                    </Button>
                    <Button 
                        onClick={handleAdd} 
                        variant="contained"
                        data-testid={`${componentName}__dialogAdd__01JK2V3XZA1H7H4Y`}
                        data-test-comment="确认添加按钮，提交输入内容并更新列表"
                    >
                        {t('EntityChipsEditor.action.add')}
                    </Button>
                </DialogActions>
            </Dialog>
        </Box>
    );
}
